// Network input hardening — testable without sockets.
pub const MAX_MESSAGE_BYTES: usize = 512;

pub fn sanitize(raw: &str) -> Result<String, String> {
    if raw.len() > MAX_MESSAGE_BYTES {
        return Err(String::from("message too long"));
    }
    let cleaned: String = raw.chars().filter(|c| !c.is_control()).collect();
    if cleaned.trim().is_empty() {
        return Err(String::from("empty message"));
    }
    Ok(cleaned)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn rejects_oversize_and_strips_control_chars() {
        assert!(sanitize(&"x".repeat(513)).is_err());
        assert_eq!(sanitize("hi\u{7}there").unwrap(), "hithere");
    }
}
